// ROTACIÓN AUTOMÁTICA DE 5 API KEYS DE GEMINI (SISTEMA ANTI-SATURACIÓN / FAILOVER)
// Coloca aquí tus 5 API Keys diferentes de Google AI Studio
const apiKeys = [
  process.env.GEMINI_API_KEY_1 || "TU_API_KEY_1_AQUI",
  process.env.GEMINI_API_KEY_2 || "TU_API_KEY_2_AQUI",
  process.env.GEMINI_API_KEY_3 || "TU_API_KEY_3_AQUI",
  process.env.GEMINI_API_KEY_4 || "TU_API_KEY_4_AQUI",
  process.env.GEMINI_API_KEY_5 || "TU_API_KEY_5_AQUI"
];

// Selecciona de manera aleatoria o secuencial para repartir la carga
const randomIndex = Math.floor(Math.random() * apiKeys.length);
const selectedKey = apiKeys[randomIndex];

return [{
  json: {
    geminiApiKey: selectedKey,
    model: "models/gemini-1.5-flash"
  }
}];

const company = $('Get Company Details').item.json;
const items = $input.all();
const pitches = items.map(it => it.json);
const baseUrl = 'https://cancheros.site';

const nowCo = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Bogota' }));
const yyyy = nowCo.getFullYear();
const mm = String(nowCo.getMonth() + 1).padStart(2, '0');
const dd = String(nowCo.getDate()).padStart(2, '0');
const todayDate = `${yyyy}-${mm}-${dd}`;

const tomorrowDateObj = new Date(nowCo.getTime() + 24 * 60 * 60 * 1000);
const tomorrowYyyy = tomorrowDateObj.getFullYear();
const tomorrowMm = String(tomorrowDateObj.getMonth() + 1).padStart(2, '0');
const tomorrowDd = String(tomorrowDateObj.getDate()).padStart(2, '0');
const tomorrowDate = `${tomorrowYyyy}-${tomorrowMm}-${tomorrowDd}`;

const currentHour = nowCo.getHours();
const currentMinutes = nowCo.getMinutes();
const currentTimeFormatted = nowCo.toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit', hour12: true });

const pitchesFormatted = pitches.map(p => ({
  id: p.id,
  name: p.name,
  type: p.type || 'Fútbol 5',
  surface: p.surface || 'Sintética',
  price: p.price_per_hour || 70000,
  priceFormatted: `$${(p.price_per_hour || 70000).toLocaleString('es-CO')}`,
  link: `${baseUrl}/cancha/${p.id}`
}));

return [{
  json: {
    companyId: company.id,
    companyName: company.name,
    todayDate,
    tomorrowDate,
    currentHour,
    currentMinutes,
    currentTimeFormatted,
    totalPitches: pitches.length,
    pitchesFormatted,
    baseUrl
  }
}];

const pitchesCtx = $('Format Pitches Context').item.json;
const currentHour = pitchesCtx.currentHour;
const currentMinutes = pitchesCtx.currentMinutes;
const todayDate = pitchesCtx.todayDate;
const tomorrowDate = pitchesCtx.tomorrowDate;
const baseUrl = 'https://cancheros.site';

function formatTime12(timeStr) {
  if (!timeStr) return '';
  const [h, m] = timeStr.split(':').map(Number);
  const period = h >= 12 ? 'PM' : 'AM';
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return `${h12}:${String(m || 0).padStart(2, '0')} ${period}`;
}

function deduplicatePitches(dataArray) {
  if (!Array.isArray(dataArray)) return [];
  const map = new Map();
  for (const item of dataArray) {
    if (item && item.pitch_id && !map.has(item.pitch_id)) {
      map.set(item.pitch_id, item);
    }
  }
  return Array.from(map.values());
}

function processAvailability(dayTitle, dateStr, dayData, isToday) {
  const cleanData = deduplicatePitches(dayData);
  if (cleanData.length === 0) {
    return `${dayTitle} (${dateStr}):\nSin datos de disponibilidad.\n`;
  }

  const parsed = [];
  for (const p of cleanData) {
    const avail = [];
    const booked = [];

    for (const s of (p.slots || [])) {
      if (s.status !== 'available') {
        booked.push(formatTime12(s.time));
        continue;
      }
      if (isToday) {
        const [h] = s.time.split(':').map(Number);
        if (h < currentHour || (h === currentHour && currentMinutes > 15)) {
          continue;
        }
      }
      avail.push(s);
    }

    parsed.push({
      id: p.pitch_id,
      name: p.pitch_name,
      type: p.pitch_type || 'Fútbol 5',
      surface: p.surface || 'Sintética',
      price: p.price_per_hour,
      link: `${baseUrl}/cancha/${p.pitch_id}`,
      avail,
      booked
    });
  }

  const firstAvail = parsed.find(p => p.avail.length > 0);

  let out = `════════════════════════════════════════\n`;
  out += `📅 ${dayTitle} (${dateStr})\n`;
  out += `════════════════════════════════════════\n`;

  if (firstAvail) {
    const suggestedSlots = firstAvail.avail.slice(0, 4).map(s => {
      const priceFormatted = (s.price || firstAvail.price || 0).toLocaleString('es-CO');
      return `${formatTime12(s.time)} ($${priceFormatted})`;
    }).join(', ');

    out += `⭐ RECOMENDACIÓN PRIORITARIA (PRIMERA CANCHA DISPONIBLE - OFRECE ESTA PARA NO SATURAR):\n`;
    out += `• Cancha: "${firstAvail.name}" (${firstAvail.type}, ${firstAvail.surface})\n`;
    out += `• Horarios disponibles sugeridos: ${suggestedSlots}\n`;
    out += `• Enlace directo para reservar: ${firstAvail.link}\n\n`;
  } else {
    out += `⚠️ TODAS LAS CANCHAS ESTÁN OCUPADAS / RESERVADAS PARA ESTA FECHA.\n\n`;
  }

  out += `📋 TODAS LAS CANCHAS DEL COMPLEJO (DISPONIBILIDAD Y ENLACES EXACTOS):\n`;
  for (const p of parsed) {
    if (p.avail.length === 0) {
      out += `• ${p.name}: TODO RESERVADO (Sin horas libres)\n  Enlace: ${p.link}\n`;
    } else {
      const slotsList = p.avail.map(s => {
        const priceFormatted = (s.price || p.price || 0).toLocaleString('es-CO');
        return `${formatTime12(s.time)} ($${priceFormatted})`;
      }).join(', ');
      out += `• ${p.name}: ${slotsList}\n  👉 Enlace oficial: ${p.link}\n`;
    }
    if (p.booked.length > 0) {
      out += `  ⛔ HORAS OCUPADAS (PROHIBIDO OFRECER): ${p.booked.join(', ')}\n`;
    }
  }

  return out;
}

let todayData = [];
let tomorrowData = [];

try {
  const allToday = $('Get Today Availability').all();
  todayData = allToday.map(i => i.json).flat();
} catch(e) {
  try {
    todayData = [$('Get Today Availability').first().json].flat();
  } catch(e2) {
    todayData = [];
  }
}

try {
  const allTomorrow = $('Get Tomorrow Availability').all();
  tomorrowData = allTomorrow.map(i => i.json).flat();
} catch(e) {
  try {
    tomorrowData = [$('Get Tomorrow Availability').first().json].flat();
  } catch(e2) {
    tomorrowData = [];
  }
}

const todayBlock = processAvailability('DISPONIBILIDAD HOY', todayDate, todayData, true);
const tomorrowBlock = processAvailability('DISPONIBILIDAD MAÑANA', tomorrowDate, tomorrowData, false);

return [{
  json: {
    ...pitchesCtx,
    availabilityContext: `${todayBlock}\n\n${tomorrowBlock}`
  }
}];

